const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const main=$('#main'), modal=$('#modal'), modalBody=$('#modalBody');
let sources=[],sourcePlans=[],coverage=[];
let currentWeek=mondayOf(new Date());
let recipeFilters={q:'',meal:'',source:'',favorites:false,ingredient:'',maxCalories:'',minProtein:'',sort:'title'};
const DAYS=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const MEALS=['breakfast','lunch','dinner','snack','dessert'];

function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function fmtDate(d){return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(d);}
function toast(msg){const n=document.createElement('div');n.className='toast';n.textContent=msg;$('#toastHost').append(n);setTimeout(()=>n.remove(),2600);}
function closeModal(){if(modal.open)modal.close();}
function openModal(html){modalBody.innerHTML=html;modal.showModal();}
function pageHead(title,sub='',actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div><div class="row">${actions}</div></div>`;}
function facts(r){return [`${(r.mealTypes?.[0]||'recipe').replace(/^./,c=>c.toUpperCase())}`,r.servingsUnknown?'Yield not listed':(r.servings?`${r.servings} serving${r.servings==1?'':'s'}`:'Servings not listed'),r.caloriesPerServing!=null?`${r.caloriesPerServing} cal`:'Calories not listed',r.proteinPerServing!=null?`${r.proteinPerServing}g protein`:'Protein not listed'].map(x=>`<span class="pill">${esc(x)}</span>`).join('');}
function recipeCard(r){const preview=(r.ingredients||[]).slice(0,5).map(i=>i.ingredientName||i.originalText).join(', ');return `<article class="card recipe-card" data-id="${esc(r.id)}"><div class="title-row"><div><div class="kicker">${esc(r.mealTypes?.[0]||'Recipe')}</div><h3>${esc(r.title)}</h3></div><button class="favorite ${r.favorite?'on':''}" data-action="favorite" data-id="${esc(r.id)}" aria-label="${r.favorite?'Remove favorite':'Add favorite'}">${r.favorite?'★':'☆'}</button></div><div class="recipe-meta">${r.caloriesPerServing!=null?`<span class="badge">${r.caloriesPerServing} cal</span>`:''}${r.proteinPerServing!=null?`<span class="badge">${r.proteinPerServing}g protein</span>`:''}${r.needsReview?'<span class="badge warn" title="Structured extraction has fields pending source audit">source review</span>':''}</div><div class="ingredients-preview">${esc(preview||'Ingredient structure pending source audit')}</div><div class="pill source-pill" title="${esc(r.sourceBook)}">${esc(r.isSource?r.sourceBook:'My Recipe')}</div><div class="actions"><button class="btn primary" data-action="open-recipe" data-id="${esc(r.id)}">View recipe</button><button class="btn" data-action="plan-recipe" data-id="${esc(r.id)}">Plan</button></div></article>`;}

async function init(){
  await Promise.all([initIngredientAliases(),initSubstitutions()]);
  const [seed,src,plans,cov]=await Promise.all([fetch('./data/recipes.json').then(r=>r.json()),fetch('./data/sources.json').then(r=>r.json()),fetch('./data/source-plans.json').then(r=>r.json()),fetch('./data/source-coverage.json').then(r=>r.json())]);
  sources=src;sourcePlans=plans;coverage=cov;
  const seedVersion=`0.2.5-${seed.length}-20260830`;await seedSourceRecipes(seed,seedVersion);await refreshRecipes();
  $('#recipeCountSide').textContent=`${recipes().length} recipes loaded`;
  bindGlobal();render();
  if('serviceWorker' in navigator && location.protocol!=='file:') navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
}

function bindGlobal(){
  window.addEventListener('hashchange',render);
  $('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){recipeFilters.q=e.target.value;go('recipes');}});
  $('#quickCookBtn').onclick=()=>go('cook-now');
  $('#menuBtn').onclick=()=>document.body.classList.toggle('drawer-open');
  document.addEventListener('click',async e=>{
    const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
    if(a==='open-recipe')await showRecipe(id);
    if(a==='favorite'){await toggleFavorite(id);toast('Favorite updated');render();}
    if(a==='plan-recipe')await showPlanRecipe(id);
    if(a==='close-modal')closeModal();
  });
  modal.addEventListener('click',e=>{if(e.target===modal)closeModal();});
}

async function render(){document.body.classList.remove('drawer-open');const r=route();$$('.nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===r.name));if(r.name==='home')await renderHome();else if(r.name==='recipes')await renderRecipes();else if(r.name==='planner')await renderPlanner();else if(r.name==='cook-now')await renderCookNow();else if(r.name==='grocery')await renderGrocery();else if(r.name==='pantry')await renderPantry();else if(r.name==='collections')await renderCollections();else if(r.name==='sources')await renderSources();else if(r.name==='settings')await renderSettings();else go('home');main.focus({preventScroll:true});}

async function renderHome(){const pan=await pantry(),plan=await loadWeek(currentWeek),g=await currentGrocery();const today=(new Date().getDay()+6)%7;const tonight=plan.entries.find(e=>e.dayIndex===today&&e.mealType==='dinner'),tonightExternal=(plan.exclusions||[]).find(e=>e.dayIndex===today&&e.mealType==='dinner');const tonightCandidate=tonight&&recipeById(tonight.recipeId),tonightR=tonightCandidate&&!tonightCandidate.bad?tonightCandidate:null;const favs=recipes().filter(r=>r.favorite).slice(0,3);const usable=pan.map(p=>p.normalized);const matches=usable.length?await matchRecipes(usable,{maxMissing:1}):[];main.innerHTML=`<section class="hero"><div><div class="kicker">Local-first cooking workspace</div><h1>Your recipes, plans, pantry, and shopping list.</h1><p>Browse the private source library, plan the week, or start with the ingredients already in your kitchen.</p><div class="hero-actions"><button class="btn primary" id="homeBrowse">Browse Recipes</button><button class="btn accent" id="homeCook">Cook With What I Have</button><button class="btn" id="homePlan">Plan My Week</button></div></div><div class="stat-cluster"><div class="stat"><strong>${recipes().length}</strong><span>recipes</span></div><div class="stat"><strong>${pan.length}</strong><span>pantry items</span></div><div class="stat"><strong>${plan.entries.length}</strong><span>planned meals</span></div><div class="stat"><strong>${g.items.filter(i=>i.checked).length}/${g.items.length}</strong><span>groceries checked</span></div></div></section><div class="dashboard-grid"><section class="card span-4"><div class="kicker">Tonight</div>${tonightR?`<h2>${esc(tonightR.title)}</h2><p class="muted">${esc(tonightR.sourceBook)}</p><button class="btn primary" data-action="open-recipe" data-id="${esc(tonightR.id)}">Open recipe</button>`:tonightExternal?`<h2>${esc(tonightExternal.note||'Meal planning not needed')}</h2><p class="muted">Dinner is marked as an external/no-plan meal.</p><button class="btn" id="dashPlanner">Open planner</button>`:'<div class="empty">No dinner planned for today.</div>'}</section><section class="card span-8"><div class="section-title"><div><div class="kicker">Cook from your kitchen</div><h2>Best pantry matches</h2></div><button class="btn" id="dashCook">See all</button></div>${matches.length?matches.slice(0,3).map(m=>`<div class="row between"><div><strong>${esc(m.recipe.title)}</strong><div class="small muted">${m.missing.length?`${m.missing.length} item${m.missing.length==1?'':'s'} missing`:'You have the required ingredients'}</div></div><span class="badge ${m.missing.length?'warn':'success'}">${m.score}%</span></div>`).join('<div class="divider"></div>'):'<div class="empty">Add pantry items to get instant meal matches.</div>'}</section><section class="card span-12"><div class="section-title"><div><div class="kicker">Favorites</div><h2>Quick access</h2></div></div><div class="recipe-grid">${favs.length?favs.map(recipeCard).join(''):'<div class="empty">Favorite recipes will appear here.</div>'}</div></section></div>`;$('#homeBrowse').onclick=()=>go('recipes');$('#homeCook').onclick=$('#dashCook').onclick=()=>go('cook-now');$('#homePlan').onclick=()=>go('planner');if($('#dashPlanner'))$('#dashPlanner').onclick=()=>go('planner');}

async function renderRecipes(){const list=searchRecipes(recipeFilters);main.innerHTML=pageHead('Recipes',`${list.length} of ${recipes().length} recipes`,`<button class="btn primary" id="addRecipeBtn">+ Custom Recipe</button>`)+`<div class="recipe-layout"><aside class="card flat filters"><div class="filter-group"><label>Search</label><input id="rq" value="${esc(recipeFilters.q)}" placeholder="Name, source, ingredient…"></div><div class="filter-group"><label>Meal</label><select id="rmeal"><option value="">All meals</option>${MEALS.map(m=>`<option value="${m}" ${recipeFilters.meal===m?'selected':''}>${m[0].toUpperCase()+m.slice(1)}</option>`).join('')}</select></div><div class="filter-group"><label>Source</label><select id="rsource"><option value="">All sources</option>${sources.map(s=>`<option value="${esc(s.file)}" ${recipeFilters.source===s.file?'selected':''}>${esc(s.title)}</option>`).join('')}<option value="__user">My recipes</option></select></div><div class="filter-group"><label>Ingredient contains</label><input id="ring" value="${esc(recipeFilters.ingredient)}" placeholder="e.g. chicken"></div><div class="two-col"><div class="field"><label>Max calories</label><input id="rcal" type="number" min="0" value="${esc(recipeFilters.maxCalories)}"></div><div class="field"><label>Min protein</label><input id="rprot" type="number" min="0" value="${esc(recipeFilters.minProtein)}"></div></div><div class="filter-group"><label>Sort</label><select id="rsort"><option value="title">Title</option><option value="calories" ${recipeFilters.sort==='calories'?'selected':''}>Calories</option><option value="protein" ${recipeFilters.sort==='protein'?'selected':''}>Protein</option></select></div><label class="check"><input id="rfav" type="checkbox" ${recipeFilters.favorites?'checked':''}> Favorites only</label><div class="divider"></div><button class="btn" id="clearFilters">Clear filters</button></aside><section><div class="recipe-grid">${list.length?list.map(recipeCard).join(''):'<div class="empty">No recipes match these filters.</div>'}</div></section></div>`;
  const apply=()=>{recipeFilters={...recipeFilters,q:$('#rq').value,meal:$('#rmeal').value,source:$('#rsource').value,ingredient:$('#ring').value,maxCalories:$('#rcal').value,minProtein:$('#rprot').value,sort:$('#rsort').value,favorites:$('#rfav').checked};renderRecipes();};['#rmeal','#rsource','#rsort','#rfav'].forEach(s=>$(s).onchange=apply);let timer;['#rq','#ring','#rcal','#rprot'].forEach(s=>$(s).oninput=()=>{clearTimeout(timer);timer=setTimeout(apply,220);});$('#clearFilters').onclick=()=>{recipeFilters={q:'',meal:'',source:'',favorites:false,ingredient:'',maxCalories:'',minProtein:'',sort:'title'};renderRecipes();};$('#addRecipeBtn').onclick=showCustomRecipeForm;
}

function cleanInstructionText(text){
  return String(text||'')
    .replace(/\u00ad/g,'')
    .replace(/[ \t]+/g,' ')
    .replace(/\s+([,.;:!?])/g,'$1')
    .replace(/^[\s—–_-]+|[\s—–_-]+$/g,'')
    .trim();
}
function displayInstructions(instructions){
  const out=[];
  for(const raw of (instructions||[])){
    let text=String(raw||'').replace(/\r?\n+/g,' ').trim();
    if(!text) continue;
    // OCR from image-heavy pages often preserves step dividers as em-dash/number/em-dash runs.
    // Split only when an explicit numbered divider is present; never split ordinary hyphenated prose.
    const marker=/\s*[—–_-]{1,4}\s*(\d{1,2})\s*[—–_-]{1,4}\s*/g;
    const matches=[...text.matchAll(marker)];
    if(matches.length){
      let cursor=0;
      for(let m=0;m<matches.length;m++){
        const hit=matches[m];
        const before=cleanInstructionText(text.slice(cursor,hit.index));
        if(before && before.length>20) out.push(before);
        const start=hit.index+hit[0].length;
        const end=m+1<matches.length?matches[m+1].index:text.length;
        const chunk=cleanInstructionText(text.slice(start,end));
        if(chunk) out.push(chunk);
        cursor=end;
      }
      if(cursor<text.length){
        const tail=cleanInstructionText(text.slice(cursor));
        if(tail && !out.includes(tail)) out.push(tail);
      }
      continue;
    }
    text=cleanInstructionText(text.replace(/^\s*\d{1,2}[.)]\s*/,''));
    if(text) out.push(text);
  }
  return out;
}
async function showRecipe(id){const r=recipeById(id);if(!r)return;const pan=await pantry();const defaultServ=r.servings||1;const ingredientRows=(serv=defaultServ)=>(r.ingredients||[]).map(i=>{const s=scaleIngredient(i,defaultServ,serv);const have=pan.find(p=>ingredientMatches(p.normalized,i.normalizedIngredient));return `<li><span>${s.displayQuantity?`<strong>${esc(s.displayQuantity)}${s.unit?' '+esc(s.unit):''}</strong> `:''}${esc(i.ingredientName||i.originalText)}${i.optional?' <span class="muted">(optional)</span>':''}</span><span class="status ${have?'have':'missing'}">${have?'✓ on hand':'not marked on hand'}</span></li>`;}).join('');openModal(`<button class="icon-btn modal-close" data-action="close-modal" aria-label="Close">×</button><div class="recipe-detail-head"><div class="kicker">${esc(r.mealTypes?.[0]||'Recipe')} · ${esc(r.isSource?r.sourceBook:'My Recipe')}</div><h1>${esc(r.title)}</h1><div class="facts">${facts(r)}</div><div class="row"><button class="btn ${r.favorite?'accent':''}" id="detailFav">${r.favorite?'★ Favorite':'☆ Favorite'}</button><button class="btn primary" id="detailPlan">Add to Meal Plan</button><button class="btn" id="detailGrocery">Add missing to Grocery List</button>${r.isSource?'<button class="btn" id="cloneRecipe">Create My Version</button>':''}<button class="btn danger" id="detailBad">Mark as Bad</button></div><p class="small muted">Source: ${esc(r.sourceBook)} · ${r.sourceUrl?`<a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">original web recipe ↗</a>`:/^https?:/.test(r.sourceFile||'')?`<a href="${esc(r.sourceFile)}" target="_blank" rel="noopener noreferrer">original web recipe ↗</a>`:(r.sourcePage?`page ${esc(r.sourcePage)}`:'imported archive')}${r.sourceTitle&&r.sourceTitle!==r.title?` · source title: ${esc(r.sourceTitle)}`:''}</p></div><div class="two-col"><section><div class="section-title"><h2>Ingredients</h2><div class="row"><button class="icon-btn" id="servMinus">−</button><strong id="servLabel">${defaultServ} serving${defaultServ==1?'':'s'}</strong><button class="icon-btn" id="servPlus">+</button></div></div><ul class="ingredient-list" id="detailIngredients">${ingredientRows()}</ul></section><section><h2>Instructions</h2>${displayInstructions(r.instructions).length?`<ol class="instruction-list">${displayInstructions(r.instructions).map(x=>`<li><div class="instruction-text">${esc(x)}</div></li>`).join('')}</ol>`:'<div class="empty">Instructions are pending source-structure review. The preserved source text is available below.</div>'}${r.tips?.length?`<h3>Tips & variations</h3><div class="stack">${r.tips.map(x=>`<p class="small">${esc(x)}</p>`).join('')}</div>`:''}</section></div>${r.rawSourceText?`<details class="card flat" style="margin-top:1rem"><summary><strong>Preserved source extraction</strong> <span class="muted">(for verification)</span></summary><div class="source-raw">${esc(r.rawSourceText)}</div></details>`:''}${r.needsReview?'<p class="small muted">Structured fields for this recipe are flagged for source audit. The original extracted source text is preserved above so no unreadable details are silently invented.</p>':''}`);
  let serv=defaultServ;const update=()=>{$('#servLabel').textContent=r.servingsUnknown?'Original recipe yield':`${serv} serving${serv==1?'':'s'}`;$('#detailIngredients').innerHTML=ingredientRows(serv);};if(r.servingsUnknown){$('#servMinus').disabled=true;$('#servPlus').disabled=true;update();}else{$('#servMinus').onclick=()=>{serv=Math.max(1,serv-1);update();};$('#servPlus').onclick=()=>{serv++;update();};}$('#detailFav').onclick=async()=>{await toggleFavorite(id);closeModal();showRecipe(id);};$('#detailPlan').onclick=()=>{closeModal();showPlanRecipe(id,serv);};$('#detailGrocery').onclick=async()=>{let g=await currentGrocery();for(const i of r.ingredients||[]){if(i.optional)continue;const have=pan.find(p=>ingredientMatches(p.normalized,i.normalizedIngredient));if(have)continue;g.items.push({id:`manual-${Date.now()}-${Math.random()}`,name:i.ingredientName,normalizedIngredient:i.normalizedIngredient,quantity:i.quantity,unit:i.unit||'',category:i.category||'Other',checked:false,manual:true,sources:[{recipeId:r.id,title:r.title}]});}await saveGrocery(g);toast('Missing ingredients added');};if($('#cloneRecipe'))$('#cloneRecipe').onclick=()=>{closeModal();showCustomRecipeForm(r);};$('#detailBad').onclick=async()=>{if(!confirm(`Mark ${r.title} as bad? It will be excluded from Recipes, Cook Now, favorites, grocery generation, and automatic meal planning until restored in Settings.`))return;await markRecipeBad(r.id,true);closeModal();toast('Recipe marked bad and excluded');render();};}

async function showPlanRecipe(id,servings=1){const r=recipeById(id);if(!r)return;openModal(`<button class="icon-btn modal-close" data-action="close-modal">×</button><h2>Add to Meal Plan</h2><p><strong>${esc(r.title)}</strong></p><div class="three-col"><div class="field"><label>Day</label><select id="planDay">${DAYS.map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select></div><div class="field"><label>Meal</label><select id="planMeal">${MEALS.map(m=>`<option value="${m}" ${r.mealTypes?.[0]===m?'selected':''}>${m[0].toUpperCase()+m.slice(1)}</option>`).join('')}</select></div><div class="field"><label>Servings</label><input type="number" id="planServ" min="1" step="1" value="${servings}"></div></div><div class="row" style="margin-top:1rem"><button class="btn primary" id="confirmPlan">Add meal</button><button class="btn" data-action="close-modal">Cancel</button></div>`);$('#confirmPlan').onclick=async()=>{await addMeal(currentWeek,Number($('#planDay').value),$('#planMeal').value,id,Number($('#planServ').value));toast('Added to meal plan');closeModal();};}

async function renderPlanner(){
  const plan=await loadWeek(currentWeek),profile=await householdProfile();
  const targets=householdTargets(profile);
  const dayNutrition=(di)=>{let c=0,p=0,kc=0,kp=0;for(const e of plan.entries.filter(x=>x.dayIndex===di)){const r=recipeById(e.recipeId);if(!r)continue;if(r.caloriesPerServing!=null){c+=r.caloriesPerServing*(e.servings||1);kc++;}if(r.proteinPerServing!=null){p+=r.proteinPerServing*(e.servings||1);kp++;}}return {c,p,kc,kp};};
  const rows=DAYS.map((day,di)=>{const dn=dayNutrition(di),ext=(plan.exclusions||[]).filter(x=>x.dayIndex===di).length;return `<div class="planner-cell planner-day"><strong>${day}</strong><div class="tiny muted">${dn.kc?Math.round(dn.c)+' cal':'nutrition pending'}${dn.kp?' · '+Math.round(dn.p)+'g protein':''}${ext?' · '+ext+' external':''}</div></div>${MEALS.map(meal=>{const entries=plan.entries.filter(e=>e.dayIndex===di&&e.mealType===meal),skip=(plan.exclusions||[]).find(x=>x.dayIndex===di&&x.mealType===meal);return `<div class="planner-cell planner-dropzone" data-day="${di}" data-meal="${meal}" data-label="${meal}">${skip?`<div class="planner-exclusion"><button class="exclusion-note" data-day="${di}" data-meal="${meal}" title="Edit note"><strong>${esc(skip.note||'Meal planning not needed')}</strong><span class="tiny">Tap to edit</span></button><button class="favorite clear-exclusion" data-day="${di}" data-meal="${meal}" aria-label="Resume meal planning">×</button></div>`:entries.map(e=>{const r=recipeById(e.recipeId);return r?`<div class="planner-recipe" data-entry="${esc(e.id)}"><button class="drag-handle" data-entry="${esc(e.id)}" aria-label="Drag ${esc(r.title)} to another meal" title="Drag to move">⋮⋮</button><button class="planner-title" data-action="open-recipe" data-id="${esc(r.id)}">${esc(r.title)} <span class="muted">${e.servings} total serving${e.servings==1?'':'s'}${targets.peopleCount>1?` · ${(e.servings/targets.peopleCount).toFixed(e.servings%targets.peopleCount?1:0)}/person`:''}</span></button><button class="remove-meal" data-entry="${esc(e.id)}" aria-label="Remove">×</button></div>`:'';}).join('')+`<div class="slot-actions"><button class="chip add-slot" data-day="${di}" data-meal="${meal}">+ Add</button><button class="chip skip-slot" data-day="${di}" data-meal="${meal}">No plan needed</button></div>`}</div>`;}).join('')}`;}).join('');
  const profileText=profile.people?.length?`${profile.people.length} ${profile.people.length===1?'person':'people'} · ${Math.round(targets.calories)} cal/day household target${targets.protein?` · ${Math.round(targets.protein)}g protein`:''}`:'No household planning profile yet';
  main.innerHTML=pageHead('Meal Planner',`Week of ${fmtDate(currentWeek)}`,`<div class="week-controls"><button class="icon-btn" id="prevWeek">←</button><button class="btn" id="todayWeek">Today</button><button class="icon-btn" id="nextWeek">→</button></div><button class="btn accent" id="autoPlan">Suggest My Week</button><button class="btn" id="clearCurrentWeek">Clear Meal Plan</button><button class="btn primary" id="makeGrocery">Generate Grocery List</button>`)+`<section class="card planner-profile-strip"><div><div class="kicker">Household planning target</div><strong>${esc(profileText)}</strong></div><button class="btn" id="editProfile">Personal Data</button></section><div class="planner-grid"><div class="planner-cell head">Day</div>${MEALS.map(m=>`<div class="planner-cell head">${m}</div>`).join('')}${rows}</div><div class="card flat planner-summary"><div class="row between"><div><strong>Planned nutrition</strong><div class="small muted">Calculated only from recipes with source-supplied calories/protein. Meals marked external are not estimated.</div></div><span>${nutritionSummary(plan)}</span></div></div>`;
  $('#prevWeek').onclick=()=>{currentWeek.setDate(currentWeek.getDate()-7);renderPlanner();};$('#nextWeek').onclick=()=>{currentWeek.setDate(currentWeek.getDate()+7);renderPlanner();};$('#todayWeek').onclick=()=>{currentWeek=mondayOf(new Date());renderPlanner();};$('#makeGrocery').onclick=async()=>{await generateGrocery(currentWeek);toast('Grocery list generated');go('grocery');};$('#autoPlan').onclick=()=>showAutoPlan(profile);$('#editProfile').onclick=()=>showHouseholdProfile();$('#clearCurrentWeek').onclick=async()=>{if(!confirm('Clear all planned recipes for this week? “No plan needed” notes will be kept.'))return;await clearWeek(currentWeek,{clearExclusions:false});toast('Meal plan cleared');renderPlanner();};
  $$('.remove-meal').forEach(b=>b.onclick=async()=>{await removeMeal(currentWeek,b.dataset.entry);renderPlanner();});$$('.add-slot').forEach(b=>b.onclick=()=>showRecipePicker(Number(b.dataset.day),b.dataset.meal));$$('.skip-slot').forEach(b=>b.onclick=async()=>{await setMealExclusion(currentWeek,Number(b.dataset.day),b.dataset.meal);renderPlanner();});$$('.clear-exclusion').forEach(b=>b.onclick=async()=>{await clearMealExclusion(currentWeek,Number(b.dataset.day),b.dataset.meal);renderPlanner();});$$('.exclusion-note').forEach(b=>b.onclick=()=>editMealExclusion(Number(b.dataset.day),b.dataset.meal));
  bindPlannerDrag();
}
function nutritionSummary(plan){let c=0,p=0,knownC=0,knownP=0;for(const e of plan.entries){const r=recipeById(e.recipeId);if(!r)continue;if(r.caloriesPerServing!=null){c+=r.caloriesPerServing*(e.servings||1);knownC++;}if(r.proteinPerServing!=null){p+=r.proteinPerServing*(e.servings||1);knownP++;}}return `${knownC?Math.round(c)+' cal':'calories incomplete'} · ${knownP?Math.round(p)+'g protein':'protein incomplete'}`;}
async function householdProfile(){let p=await setting('householdProfile',null);if(!p||!Array.isArray(p.people)||!p.people.length)p={people:[{id:'person-1',name:'Person 1',gender:'woman',targetCalories:2000,targetProtein:75}],favoriteRecipeIds:[]};p.plannerPreferences={packableWeekdayLunches:true,quickWeekdayDinners:true,weekendFlexibility:true,...(p.plannerPreferences||{})};return p;}
function defaultTargetsForGender(g){return g==='man'?{calories:2500,protein:95}:g==='woman'?{calories:2000,protein:75}:{calories:2250,protein:85};}
async function showHouseholdProfile(){const profile=await householdProfile();openModal(`<button class="icon-btn modal-close" data-action="close-modal">×</button><h2>Personal Data · Meal Planning</h2><p class="muted">Set the people this plan should feed and the daily planning targets for each person. Gender supplies a general starting target only; calories and protein are editable so you can use the requirements appropriate for each person.</p><div id="peopleEditor" class="stack"></div><button class="btn" id="addPerson" style="margin-top:.8rem">+ Add person</button><div class="divider"></div><div class="row"><button class="btn primary" id="saveHousehold">Save Personal Data</button><button class="btn" data-action="close-modal">Cancel</button></div>`);const host=$('#peopleEditor');const add=(person={})=>{const n=host.children.length+1,d=defaultTargetsForGender(person.gender||'woman'),row=document.createElement('div');row.className='card flat person-row';row.innerHTML=`<div class="person-grid"><div class="field"><label>Name</label><input type="text" class="person-name" value="${esc(person.name||'Person '+n)}"></div><div class="field"><label>Gender</label><select class="person-gender"><option value="woman" ${(person.gender||'woman')==='woman'?'selected':''}>Woman</option><option value="man" ${person.gender==='man'?'selected':''}>Man</option><option value="other" ${person.gender==='other'?'selected':''}>Other / custom</option><option value="unspecified" ${person.gender==='unspecified'?'selected':''}>Prefer not to say</option></select></div><div class="field"><label>Daily calories</label><input class="person-cal" type="number" min="500" step="50" value="${person.targetCalories||d.calories}"></div><div class="field"><label>Protein (g/day)</label><input class="person-pro" type="number" min="0" step="5" value="${person.targetProtein||d.protein}"></div><button class="icon-btn remove-person" aria-label="Remove person">×</button></div>`;const gender=row.querySelector('.person-gender');gender.onchange=()=>{const v=defaultTargetsForGender(gender.value);row.querySelector('.person-cal').value=v.calories;row.querySelector('.person-pro').value=v.protein;};row.querySelector('.remove-person').onclick=()=>{if(host.children.length>1)row.remove();};host.append(row);};profile.people.forEach(add);$('#addPerson').onclick=()=>add({gender:'woman'});$('#saveHousehold').onclick=async()=>{const people=[...host.children].map((row,i)=>({id:`person-${i+1}`,name:row.querySelector('.person-name').value.trim()||`Person ${i+1}`,gender:row.querySelector('.person-gender').value,targetCalories:Number(row.querySelector('.person-cal').value)||0,targetProtein:Number(row.querySelector('.person-pro').value)||0}));await setSetting('householdProfile',{...profile,people});closeModal();toast('Personal data saved');if(route().name==='planner')renderPlanner();};}
function favoritePickerRow(value=''){return `<div class="favorite-plan-row"><input type="text" class="favorite-plan-input" list="favoriteRecipeOptions" value="${esc(value)}" placeholder="Choose a favorite meal…"><button class="icon-btn remove-favorite-plan" aria-label="Remove favorite meal">×</button></div>`;}
async function showAutoPlan(profileArg=null){const profile=profileArg||await householdProfile(),favorites=(profile.favoriteRecipeIds||[]).map(id=>recipeById(id)?.title).filter(Boolean),prefs=profile.plannerPreferences||{};openModal(`<button class="icon-btn modal-close" data-action="close-modal">×</button><h2>Suggest My Week</h2><p class="muted">Recipe Manager uses the household calorie/protein targets, appropriate total recipe servings, and your normal workweek routine. Weekday lunches favor compact packable meals, weekday dinners favor quicker/easier recipes, and weekends can use more involved meals.</p><div class="card flat"><div class="kicker">Planning for</div><strong>${profile.people.map(p=>`${esc(p.name)} (${esc(p.gender)})`).join(' · ')}</strong></div><h3 style="margin-top:1rem">Meals to plan</h3><div class="chip-row">${MEALS.map(m=>`<label class="check"><input class="auto-meal" type="checkbox" value="${m}" ${!['snack','dessert'].includes(m)?'checked':''}> ${m[0].toUpperCase()+m.slice(1)}</label>`).join('')}</div><h3 style="margin-top:1rem">Workweek preferences</h3><div class="stack compact-stack"><label class="check"><input type="checkbox" id="prefPackLunch" ${prefs.packableWeekdayLunches!==false?'checked':''}> Weekday lunches should be compact and packable</label><label class="check"><input type="checkbox" id="prefQuickDinner" ${prefs.quickWeekdayDinners!==false?'checked':''}> Weekday dinners should favor quick/easy preparation</label><label class="check"><input type="checkbox" id="prefWeekend" ${prefs.weekendFlexibility!==false?'checked':''}> Use weekends for more involved recipes when useful</label></div><p class="tiny muted">These are ranking preferences, not hard filters, so the planner can still find a nutritionally suitable meal when the recipe library has limited options.</p><h3 style="margin-top:1rem">Favorite meals to include</h3><p class="small muted">Add as many as you want. Each selected favorite is placed at least once when a compatible open meal slot exists.</p><datalist id="favoriteRecipeOptions">${recipes().map(r=>`<option value="${esc(r.title)}"></option>`).join('')}</datalist><div id="favoritePlanRows" class="stack compact-stack">${(favorites.length?favorites:['']).map(favoritePickerRow).join('')}</div><button class="btn" id="addFavoritePlan" style="margin-top:.6rem">+ Add favorite meal</button><div class="divider"></div><label class="check"><input type="checkbox" id="replaceAutoPlan"> Replace existing planned recipes in the selected meal types</label><p class="tiny muted">Meals marked “planning not needed” are always preserved and are never replaced. Meal calorie shares stay fixed (for example, planning only dinners still targets the dinner share rather than an entire day of calories).</p><div class="row"><button class="btn primary" id="generateAutoPlan">Build suggested week</button><button class="btn" id="profileFromAuto">Edit Personal Data</button></div>`);const host=$('#favoritePlanRows');const bind=()=>{$$('.remove-favorite-plan').forEach(b=>b.onclick=()=>{if(host.children.length>1)b.parentElement.remove();else b.parentElement.querySelector('input').value='';});};bind();$('#addFavoritePlan').onclick=()=>{host.insertAdjacentHTML('beforeend',favoritePickerRow(''));bind();};$('#profileFromAuto').onclick=()=>{closeModal();showHouseholdProfile();};$('#generateAutoPlan').onclick=async()=>{const mealTypes=$$('.auto-meal').filter(x=>x.checked).map(x=>x.value);if(!mealTypes.length){alert('Choose at least one meal type to plan.');return;}const titles=$$('.favorite-plan-input').map(x=>x.value.trim()).filter(Boolean),ids=[];for(const t of titles){const r=recipes().find(x=>x.title.toLowerCase()===t.toLowerCase());if(r)ids.push(r.id);}const plannerPreferences={packableWeekdayLunches:$('#prefPackLunch').checked,quickWeekdayDinners:$('#prefQuickDinner').checked,weekendFlexibility:$('#prefWeekend').checked};const updatedProfile={...profile,favoriteRecipeIds:ids,plannerPreferences};await setSetting('householdProfile',updatedProfile);await autoPlanWeek(currentWeek,recipes(),updatedProfile,ids,{mealTypes,replace:$('#replaceAutoPlan').checked,...plannerPreferences});closeModal();toast('Suggested week created');renderPlanner();};}
function bindPlannerDrag(){let dragging=null,ghost=null;$$('.drag-handle').forEach(h=>{h.addEventListener('pointerdown',e=>{const card=h.closest('.planner-recipe');dragging=card.dataset.entry;h.setPointerCapture?.(e.pointerId);card.classList.add('dragging');ghost=card.cloneNode(true);ghost.classList.add('planner-ghost');document.body.append(ghost);moveGhost(e);e.preventDefault();});h.addEventListener('pointermove',e=>{if(!dragging)return;moveGhost(e);$$('.planner-dropzone').forEach(z=>z.classList.remove('drop-target'));document.elementFromPoint(e.clientX,e.clientY)?.closest('.planner-dropzone')?.classList.add('drop-target');});h.addEventListener('pointerup',async e=>{if(!dragging)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.planner-dropzone');const id=dragging;dragging=null;ghost?.remove();ghost=null;$$('.planner-dropzone').forEach(z=>z.classList.remove('drop-target'));$$('.planner-recipe.dragging').forEach(x=>x.classList.remove('dragging'));if(target){await moveMeal(currentWeek,id,Number(target.dataset.day),target.dataset.meal);renderPlanner();}});h.addEventListener('pointercancel',()=>{dragging=null;ghost?.remove();ghost=null;$$('.planner-recipe.dragging').forEach(x=>x.classList.remove('dragging'));});});function moveGhost(e){if(ghost){ghost.style.left=(e.clientX+12)+'px';ghost.style.top=(e.clientY+12)+'px';}}}
function showRecipePicker(day,meal){const list=recipes().filter(r=>(r.mealTypes||[]).includes(meal)).slice(0,120);openModal(`<button class="icon-btn modal-close" data-action="close-modal">×</button><h2>Add ${esc(meal)} · ${DAYS[day]}</h2><input id="pickSearch" placeholder="Search ${esc(meal)} recipes…"><div class="stack" id="pickList" style="margin-top:.8rem">${pickerRows(list)}</div>`);$('#pickSearch').oninput=e=>{$('#pickList').innerHTML=pickerRows(recipes().filter(r=>(r.mealTypes||[]).includes(meal)&&r.title.toLowerCase().includes(e.target.value.toLowerCase())).slice(0,120));bindPicker();};bindPicker();function pickerRows(a){return a.map(r=>`<button class="btn pick-recipe" data-id="${esc(r.id)}" style="text-align:left"><strong>${esc(r.title)}</strong><br><span class="tiny muted">${esc(r.sourceBook)}${r.caloriesPerServing!=null?` · ${r.caloriesPerServing} cal/serving`:''}</span></button>`).join('');}function bindPicker(){$$('.pick-recipe').forEach(b=>b.onclick=async()=>{await addMeal(currentWeek,day,meal,b.dataset.id,1);closeModal();renderPlanner();});}}

function matchCard(m){const r=m.recipe,missing=m.missing||[],matched=m.queryHits||[];const missingHtml=missing.length?`<div class="match-detail missing-block"><strong>Missing ${missing.length}</strong><div class="match-chips">${missing.map(x=>`<span class="chip missing-chip">${esc(x)}</span>`).join('')}</div></div>`:`<div class="match-detail"><span class="badge success">No required ingredients missing</span></div>`;const queryHtml=m.queryTotal?`<div class="small muted">Specified ingredient matches: <strong>${matched.length}/${m.queryTotal}</strong>${matched.length?` · ${matched.map(esc).join(', ')}`:''}</div>`:'';const subs=m.substitutions?.length?`<div class="small muted">Substitutions: ${m.substitutions.map(x=>`${esc(x.need)} → ${esc(x.using)}`).join(', ')}</div>`:'';return `<article class="card match-card"><div class="match-score ${missing.length?'':'complete'}">${m.score}%</div><div><div class="row between"><div><div class="kicker">${esc(r.mealTypes?.[0]||'Recipe')} · ${esc(r.sourceBook)}</div><h3>${esc(r.title)}</h3></div><span class="badge ${missing.length?'warn':'success'}">${missing.length} missing</span></div>${queryHtml}${missingHtml}${subs}</div><button class="btn primary" data-action="open-recipe" data-id="${esc(r.id)}">View recipe</button></article>`;}

async function renderCookNow(){
  const pan=await pantry();
  const saved=await setting('cookIngredientFields',[]);
  const initial=Array.isArray(saved)&&saved.length?saved:['','',''];
  const suggestions=[...new Set(recipes().flatMap(r=>(r.ingredients||[]).flatMap(i=>[i.ingredientName,i.normalizedIngredient]).filter(Boolean)))].sort((a,b)=>a.localeCompare(b));
  main.innerHTML=pageHead('Cook Now','Find recipes by what you have — or simply by an ingredient you want to use')+`<div class="two-col cook-now-layout"><section class="card"><div class="section-title"><div><div class="kicker">Ingredient finder</div><h2>What do you have?</h2></div><button class="btn" id="addCookField">+ Add ingredient</button></div><p class="muted">Add one or more ingredients. Choose a search mode depending on whether you want close matches or every recipe containing what you typed.</p><div id="cookFields" class="cook-fields"></div><div class="cook-control-grid"><label class="check"><input type="checkbox" id="includePantry" checked> Include ${pan.length} pantry items</label><label class="field compact"><span>Search mode</span><select id="cookMode"><option value="best">Best matches</option><option value="contains-all">Contains all specified ingredients</option><option value="contains-any">Contains any specified ingredient</option></select></label><label class="field compact" id="missingLimitField"><span>Missing allowed</span><select id="maxMissing">${Array.from({length:11},(_,i)=>`<option value="${i}" ${i===5?'selected':''}>${i}</option>`).join('')}<option value="any">Any number</option></select></label><label class="field compact"><span>Meal</span><select id="cookMeal"><option value="">Any meal</option>${MEALS.map(m=>`<option value="${m}">${m[0].toUpperCase()+m.slice(1)}</option>`).join('')}</select></label></div><div class="mode-help small muted" id="modeHelp"></div><div class="row" style="margin-top:1rem"><button class="btn primary" id="findMeals">Find recipes</button><button class="btn" id="clearCookFields">Clear</button></div></section><section class="card"><div class="kicker">Optional priority</div><h2>Use something up</h2><p class="muted">Choose an ingredient you especially want the results to use. This boosts matching recipes without making it mandatory.</p><div class="cook-autocomplete" id="useUpWrap"><input id="useUp" autocomplete="off" placeholder="e.g. spinach"><div class="ingredient-menu" hidden></div></div><div class="divider"></div><p class="small muted"><strong>Contains modes ignore the missing limit.</strong> They show recipes containing the specified ingredient(s), then clearly show how many required ingredients you still need and exactly what they are.</p><div class="pill">Strict source substitutions</div></section></div><section style="margin-top:1rem"><div class="section-title"><h2>Matches</h2><span id="matchCount" class="muted"></span></div><div class="stack" id="matchResults"><div class="empty">Add an ingredient, choose a search mode, then select Find recipes.</div></div></section>`;
  const ranked=(q)=>{q=q.trim().toLowerCase();if(!q)return[];return suggestions.filter(x=>x.toLowerCase().includes(q)).sort((a,b)=>{const A=a.toLowerCase().startsWith(q)?0:1,B=b.toLowerCase().startsWith(q)?0:1;return A-B||a.length-b.length||a.localeCompare(b)}).slice(0,8);};
  function bindAutocomplete(input,menu){let active=-1;const draw=()=>{const list=ranked(input.value);active=-1;menu.innerHTML=list.map(x=>`<button type="button" class="ingredient-option" data-value="${esc(x)}">${esc(x)}</button>`).join('');menu.hidden=!list.length;menu.querySelectorAll('.ingredient-option').forEach(b=>b.onmousedown=e=>{e.preventDefault();input.value=b.dataset.value;menu.hidden=true;input.focus();});};input.oninput=draw;input.onfocus=()=>{if(input.value.trim())draw();};input.onkeydown=e=>{const opts=[...menu.querySelectorAll('.ingredient-option')];if(e.key==='ArrowDown'&&opts.length){e.preventDefault();active=Math.min(active+1,opts.length-1);}else if(e.key==='ArrowUp'&&opts.length){e.preventDefault();active=Math.max(active-1,0);}else if(e.key==='Enter'&&active>=0&&opts[active]){e.preventDefault();input.value=opts[active].dataset.value;menu.hidden=true;}else if(e.key==='Escape'){menu.hidden=true;}opts.forEach((o,i)=>o.classList.toggle('active',i===active));};input.onblur=()=>setTimeout(()=>menu.hidden=true,120);}
  const host=$('#cookFields');
  const addField=(value='')=>{const row=document.createElement('div');row.className='cook-field-row';row.innerHTML=`<div class="cook-autocomplete"><input class="cook-ingredient" autocomplete="off" value="${esc(value)}" placeholder="Start typing an ingredient…"><div class="ingredient-menu" hidden></div></div><button class="icon-btn remove-cook-field" aria-label="Remove ingredient">×</button>`;const input=row.querySelector('input'),menu=row.querySelector('.ingredient-menu');bindAutocomplete(input,menu);row.querySelector('.remove-cook-field').onclick=()=>{if($$('.cook-field-row').length>1)row.remove();else input.value='';};host.append(row);};
  initial.forEach(addField);bindAutocomplete($('#useUp'),$('#useUpWrap .ingredient-menu'));
  $('#addCookField').onclick=()=>{addField('');host.lastElementChild.querySelector('input').focus();};
  $('#clearCookFields').onclick=()=>{$$('.cook-ingredient').forEach((x,i)=>{if(i<3)x.value='';else x.closest('.cook-field-row').remove();});$('#useUp').value='';};
  const updateModeHelp=()=>{const mode=$('#cookMode').value;$('#missingLimitField').classList.toggle('disabled-control',mode!=='best');$('#maxMissing').disabled=mode!=='best';$('#modeHelp').textContent=mode==='best'?'Best matches uses the missing-ingredient limit and ranks recipes by how much of the required ingredient list you already have.':mode==='contains-all'?'Contains all shows every recipe containing every ingredient you typed, regardless of how many other required ingredients are missing.':'Contains any shows every recipe containing at least one ingredient you typed, regardless of how many other required ingredients are missing.';};
  $('#cookMode').onchange=updateModeHelp;updateModeHelp();
  $('#findMeals').onclick=async()=>{const fields=$$('.cook-ingredient').map(x=>x.value.trim()).filter(Boolean);await setSetting('cookIngredientFields',fields.length?fields:['','','']);const query=fields.map(normalizeIngredient).filter(Boolean);const mode=$('#cookMode').value;if(mode!=='best'&&!query.length){$('#matchCount').textContent='';$('#matchResults').innerHTML='<div class="empty">Enter at least one ingredient for a Contains search.</div>';return;}let have=[...query];if($('#includePantry').checked)have.push(...pan.map(p=>p.normalized));have=[...new Set(have.filter(Boolean))];const use=$('#useUp').value.trim()?[normalizeIngredient($('#useUp').value.trim())]:[];const limit=$('#maxMissing').value==='any'?Infinity:Number($('#maxMissing').value);const matches=await matchRecipes(have,{maxMissing:limit,meal:$('#cookMeal').value,strict:true,useUp:use,queryIngredients:query,mode});$('#matchCount').textContent=`${matches.length} match${matches.length===1?'':'es'}`;$('#matchResults').innerHTML=matches.length?matches.slice(0,200).map(matchCard).join(''):'<div class="empty">No recipes matched those settings. Try Contains any specified ingredient or choose Any number for missing ingredients.</div>';};
}

async function renderGrocery(){const g=await currentGrocery();const cats=[...new Set(g.items.map(i=>i.category||'Other'))].sort();main.innerHTML=pageHead('Grocery List',g.generatedAt?`Generated ${new Date(g.generatedAt).toLocaleString()}`:'No generated list yet',`<button class="btn primary" id="regenGrocery">Generate from Current Week</button><button class="btn" id="copyGrocery">Copy Text</button><button class="btn" id="addGrocery">+ Item</button>`)+`${g.items.length?`<div class="grocery-columns">${cats.map(cat=>`<section class="card"><div class="section-title"><h2>${esc(cat)}</h2><span class="muted">${g.items.filter(i=>(i.category||'Other')===cat&&!i.checked).length} left</span></div>${g.items.filter(i=>(i.category||'Other')===cat).map(i=>`<div class="grocery-item ${i.checked?'checked':''}"><input class="gcheck" data-id="${esc(i.id)}" type="checkbox" ${i.checked?'checked':''}><div class="item-text"><strong>${esc(i.name||i.normalizedIngredient)}</strong> <span class="muted">${esc(displayGroceryQuantity(i))}</span>${i.checkOnHand?'<div class="tiny warn">Check quantity on hand</div>':''}${i.sources?.length?`<details><summary class="tiny muted">Needed for ${i.sources.length} recipe${i.sources.length==1?'':'s'}</summary><div class="tiny">${i.sources.map(s=>esc(s.title)).join('<br>')}</div></details>`:''}</div><button class="favorite gdelete" data-id="${esc(i.id)}">×</button></div>`).join('')}</section>`).join('')}</div>`:'<div class="empty">Generate a grocery list from the Meal Planner, or add an item manually.</div>'}`;$('#regenGrocery').onclick=async()=>{await generateGrocery(currentWeek);renderGrocery();toast('List regenerated');};$('#copyGrocery').onclick=async()=>{const txt=cats.map(c=>`${c.toUpperCase()}\n`+g.items.filter(i=>(i.category||'Other')===c&&!i.checked).map(i=>`- ${i.name} ${displayGroceryQuantity(i)}`.trim()).join('\n')).join('\n\n');await navigator.clipboard.writeText(txt);toast('Grocery list copied');};$('#addGrocery').onclick=()=>showAddGrocery(g);$$('.gcheck').forEach(c=>c.onchange=async()=>{const item=g.items.find(i=>i.id===c.dataset.id);item.checked=c.checked;await saveGrocery(g);renderGrocery();});$$('.gdelete').forEach(b=>b.onclick=async()=>{g.items=g.items.filter(i=>i.id!==b.dataset.id);await saveGrocery(g);renderGrocery();});}
function showAddGrocery(g){openModal(`<button class="icon-btn modal-close" data-action="close-modal">×</button><h2>Add Grocery Item</h2><div class="stack"><div class="field"><label>Item</label><input id="gName"></div><div class="two-col"><div class="field"><label>Quantity</label><input id="gQty" type="number" step="any"></div><div class="field"><label>Unit</label><input id="gUnit"></div></div><div class="field"><label>Category</label><select id="gCat">${['Produce','Meat','Seafood','Dairy','Eggs','Bakery','Grains/Pasta','Canned/Jarred','Pantry','Spices/Seasonings','Condiments/Sauces','Frozen','Snacks','Other'].map(c=>`<option>${c}</option>`).join('')}</select></div><button class="btn primary" id="gSave">Add</button></div>`);$('#gSave').onclick=async()=>{const name=$('#gName').value.trim();if(!name)return;g.items.push({id:`manual-${Date.now()}`,name,normalizedIngredient:normalizeIngredient(name),quantity:$('#gQty').value?Number($('#gQty').value):null,unit:$('#gUnit').value.trim(),category:$('#gCat').value,checked:false,manual:true,sources:[]});await saveGrocery(g);closeModal();renderGrocery();};}

async function renderPantry(){const a=(await pantry()).sort((x,y)=>x.name.localeCompare(y.name));main.innerHTML=pageHead('Pantry','Track ingredients already on hand',`<button class="btn primary" id="addPantryBtn">+ Add Item</button>`)+`<section class="card">${a.length?a.map(p=>`<div class="pantry-row"><div><strong>${esc(p.name)}</strong><div class="tiny muted">${esc(p.normalized)}${p.staple?' · always on hand':''}${p.opened?' · opened':''}</div></div><div>${p.quantity!=null?esc(formatQuantity(p.quantity)):'—'}</div><div>${esc(p.unit||'')}</div><div class="hide-mobile">${esc(p.location||'Pantry')}${p.useBy?` · use by ${esc(p.useBy)}`:''}</div><button class="favorite pdelete" data-id="${esc(p.id)}">×</button></div>`).join(''):'<div class="empty">No pantry items yet. You can still use Cook Now without building a permanent inventory.</div>'}</section>`;$('#addPantryBtn').onclick=showPantryForm;$$('.pdelete').forEach(b=>b.onclick=async()=>{await deletePantryItem(b.dataset.id);renderPantry();});}
function showPantryForm(){openModal(`<button class="icon-btn modal-close" data-action="close-modal">×</button><h2>Add Pantry Item</h2><div class="stack"><div class="field"><label>Ingredient</label><input id="pName" autofocus></div><div class="three-col"><div class="field"><label>Quantity</label><input id="pQty" type="number" step="any"></div><div class="field"><label>Unit</label><input id="pUnit" placeholder="cup, oz, pieces…"></div><div class="field"><label>Location</label><select id="pLoc"><option>Pantry</option><option>Refrigerator</option><option>Freezer</option></select></div></div><div class="field"><label>Use-by date (optional)</label><input id="pDate" type="date"></div><div class="row"><label class="check"><input id="pStaple" type="checkbox"> Always on hand</label><label class="check"><input id="pOpened" type="checkbox"> Opened / use soon</label></div><button class="btn primary" id="pSave">Save</button></div>`);$('#pSave').onclick=async()=>{if(!$('#pName').value.trim())return;await savePantryItem({name:$('#pName').value,quantity:$('#pQty').value,unit:$('#pUnit').value,location:$('#pLoc').value,useBy:$('#pDate').value,staple:$('#pStaple').checked,opened:$('#pOpened').checked});closeModal();renderPantry();};}

async function renderCollections(){const fav=recipes().filter(r=>r.favorite),want=recipes().filter(r=>r.wantToTry),made=recipes().filter(r=>r.timesMade>0);main.innerHTML=pageHead('Collections','Personal organization across the recipe library')+`<div class="three-col"><section class="card"><div class="kicker">Favorites</div><h2>${fav.length}</h2><p class="muted">Recipes you starred.</p><button class="btn" id="viewFav">View favorites</button></section><section class="card"><div class="kicker">Want to Try</div><h2>${want.length}</h2><p class="muted">Recipes marked for later.</p></section><section class="card"><div class="kicker">Made Before</div><h2>${made.length}</h2><p class="muted">Recipes with cooking history.</p></section></div><section style="margin-top:1rem"><div class="recipe-grid">${fav.slice(0,12).map(recipeCard).join('')||'<div class="empty">Star a recipe to build your Favorites collection.</div>'}</div></section>`;$('#viewFav').onclick=()=>{recipeFilters.favorites=true;go('recipes');};}

async function renderSources(){main.innerHTML=pageHead('Sources','Recipe sources and import provenance')+`<div class="recipe-grid">${sources.map(s=>{const c=coverage.find(x=>x.file===s.file)||{recipesImported:0,needsReview:0};return `<article class="card source-card"><div class="kicker">Source book</div><h2>${esc(s.title)}</h2><p class="muted">${esc(s.file)}</p><div class="row"><span class="badge">${c.recipesImported} recipes</span>${c.needsReview?`<span class="badge warn">${c.needsReview} structured records to audit</span>`:'<span class="badge success">structured audit clear</span>'}</div><div class="coverage-bar"><span style="width:${c.recipesImported?Math.max(10,100-c.needsReview/c.recipesImported*100):0}%"></span></div><div class="row"><button class="btn sourceRecipesBtn" data-file="${esc(s.file)}">Browse recipes</button><button class="btn sourcePlanBtn" data-title="${esc(s.title)}">Source plans</button></div></article>`}).join('')}</div><section class="card flat" style="margin-top:1rem"><h2>Provenance policy</h2><p class="muted">Recipes retain their source book/archive and provenance. Imported archive recipes keep their original web link when provided. Derived tags and normalized ingredients support searching and shopping without replacing the supplied source data.</p></section>`;$$('.sourceRecipesBtn').forEach(b=>b.onclick=()=>{recipeFilters={...recipeFilters,source:b.dataset.file};go('recipes');});$$('.sourcePlanBtn').forEach(b=>b.onclick=()=>showSourcePlans(b.dataset.title));}
function showSourcePlans(title){const p=sourcePlans.filter(x=>x.sourceBook===title);openModal(`<button class="icon-btn modal-close" data-action="close-modal">×</button><h2>${esc(title)} — Source Plans</h2>${p.length?p.map(x=>`<details class="card flat" open><summary><strong>Week ${x.week}</strong></summary><h3>Menu</h3><div class="source-raw">${esc(x.menuText)}</div><h3>Original grocery list</h3><div class="source-raw">${esc(x.groceryText)}</div><h3>Meal prep</h3><div class="source-raw">${esc(x.mealPrepText)}</div></details>`).join(''):'<div class="empty">Source plan extraction for this book is still in the data-audit phase.</div>'}`);}

async function renderSettings(){const seed=await setting('seedVersion',''),profile=await householdProfile(),targets=householdTargets(profile);main.innerHTML=pageHead('Settings','Local data, backup, personal planning targets, and source-database management')+`<div class="two-col"><section class="card"><h2>Personal Data · Meal Planning</h2><p class="muted">${profile.people.length} ${profile.people.length===1?'person':'people'} · household target ${Math.round(targets.calories)} cal/day${targets.protein?` · ${Math.round(targets.protein)}g protein/day`:''}.</p><p class="tiny muted">Gender is used only to provide an editable starting target. Recipe Manager does not infer medical nutrition needs.</p><button class="btn primary" id="editHouseholdSettings">Edit people & targets</button></section><section class="card"><h2>Backup & Restore</h2><p class="muted">Backups contain your personal data, including household planning settings. Source recipes are versioned seed data and can be reloaded from the application package.</p><div class="row"><button class="btn primary" id="exportBtn">Export Backup</button><button class="btn" id="importBtn">Import Backup</button></div></section><section class="card"><h2>Recipe database</h2><p class="muted">Seed version: ${esc(seed)}</p><div class="row"><button class="btn" id="reloadSeed">Reload original recipe database</button></div></section><section class="card"><h2>Bad Recipes</h2><p class="muted">${badRecipes().length} recipe${badRecipes().length===1?'':'s'} currently excluded from normal app use. Bad markings are included in your backup save data.</p><button class="btn" id="manageBadRecipes">Manage / Restore Bad Recipes</button></section><section class="card"><h2>Local hosting</h2><p class="muted">Recipe Manager is a static web application. IndexedDB is specific to the browser origin you use, so a different hostname, port, browser, or device has separate local data.</p></section><section class="card"><h2>Danger zone</h2><div class="row"><button class="btn danger" id="clearPantry">Clear Pantry</button><button class="btn danger" id="clearGrocery">Clear Grocery List</button><button class="btn danger" id="clearPlans">Clear Meal Plans</button></div></section></div>`;$('#editHouseholdSettings').onclick=showHouseholdProfile;$('#manageBadRecipes').onclick=showBadRecipeManager;$('#exportBtn').onclick=async()=>{const obj=await exportBackup();download(JSON.stringify(obj,null,2),`Recipe Manager Backup ${new Date().toISOString().slice(0,10)}.json`,'application/json');};$('#importBtn').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{await importBackup(JSON.parse(await f.text()),false);await refreshRecipes();toast('Backup merged');renderSettings();}catch(err){alert(err.message);}e.target.value='';};$('#reloadSeed').onclick=async()=>{if(!confirm('Reload the source recipe database from this release? Your personal data will be preserved.'))return;const seed=await fetch('./data/recipes.json').then(r=>r.json());await clearStore('sourceRecipes');for(const r of seed)await put('sourceRecipes',r);await refreshRecipes();toast('Source database reloaded');};$('#clearPantry').onclick=async()=>{if(confirm('Clear all pantry items?')){await clearStore('pantry');toast('Pantry cleared');}};$('#clearGrocery').onclick=async()=>{if(confirm('Clear grocery lists?')){await clearStore('grocery');toast('Grocery list cleared');}};$('#clearPlans').onclick=async()=>{if(confirm('Clear meal-plan history?')){await clearStore('mealPlans');toast('Meal plans cleared');}};}
function showBadRecipeManager(){const bad=badRecipes().sort((x,y)=>x.title.localeCompare(y.title));openModal(`<button class="icon-btn modal-close" data-action="close-modal">×</button><h2>Bad Recipes</h2><p class="muted">These recipes are excluded from all normal recipe discovery and planning. Restore any recipe here if you marked it by mistake.</p>${bad.length?`<div class="stack">${bad.map(r=>`<div class="card flat row between"><div><strong>${esc(r.title)}</strong><div class="tiny muted">${esc(r.sourceBook)}</div></div><button class="btn restore-bad" data-id="${esc(r.id)}">Restore</button></div>`).join('')}</div>`:'<div class="empty">No recipes are marked bad.</div>'}`);$$('.restore-bad').forEach(b=>b.onclick=async()=>{await markRecipeBad(b.dataset.id,false);toast('Recipe restored');showBadRecipeManager();});}

function download(text,name,type){const b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500);}

function showCustomRecipeForm(base=null){const b=base||{};const ingredients=(b.ingredients||[]).map(i=>i.originalText).join('\n');const instructions=(b.instructions||[]).join('\n');openModal(`<button class="icon-btn modal-close" data-action="close-modal">×</button><h2>${base?'Create My Version':'Add Custom Recipe'}</h2>${base?`<p class="muted">Based on: ${esc(base.title)}</p>`:''}<div class="stack"><div class="field"><label>Recipe title</label><input id="cTitle" value="${esc(base?base.title+' — My Version':'')}"></div><div class="three-col"><div class="field"><label>Meal</label><select id="cMeal">${MEALS.map(m=>`<option ${base?.mealTypes?.[0]===m?'selected':''}>${m}</option>`).join('')}</select></div><div class="field"><label>Servings</label><input id="cServ" type="number" min="1" value="${base?.servings||1}"></div><div class="field"><label>Calories/serving (optional)</label><input id="cCal" type="number" value="${base?.caloriesPerServing??''}"></div></div><div class="field"><label>Ingredients — one per line</label><textarea id="cIng">${esc(ingredients)}</textarea></div><div class="field"><label>Instructions — one step per line</label><textarea id="cIns">${esc(instructions)}</textarea></div><button class="btn primary" id="cSave">Save Recipe</button></div>`);$('#cSave').onclick=async()=>{const title=$('#cTitle').value.trim();if(!title)return;const id=`user-${Date.now()}-${title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;const ingredients=$('#cIng').value.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>({originalText:x,quantity:null,unit:null,ingredientName:x,normalizedIngredient:normalizeIngredient(x),optional:/optional/i.test(x),group:'Ingredients',category:'Other'}));const r={id,title,normalizedTitle:title.toLowerCase(),sourceBook:'My Recipes',sourceFile:'user',sourcePage:'',sourceSection:$('#cMeal').value,recipeFamily:base?.recipeFamily||title,mealTypes:[$('#cMeal').value],servings:Number($('#cServ').value)||1,caloriesPerServing:$('#cCal').value?Number($('#cCal').value):null,proteinPerServing:null,description:'',ingredients,instructions:$('#cIns').value.split('\n').map(x=>x.trim()).filter(Boolean),tips:[],variations:[],substitutions:[],tags:[$('#cMeal').value],derivedTags:[],basedOn:base?.id||null,needsReview:false};await saveUserRecipe(r);closeModal();toast('Custom recipe saved');go('recipes');};}

init().catch(err=>{console.error(err);main.innerHTML=`<div class="card"><h1>Recipe Manager could not start</h1><p>${esc(err.message)}</p><p class="muted">Make sure the application is being served through a static HTTP server rather than opened directly from a file URL.</p></div>`;});
